from pathlib import Path
import json,re
ROOT=Path(__file__).resolve().parents[2]; specs=json.loads((ROOT/'scripts/native/game-drills-source.json').read_text()); out={}
HEADER='#include <assert.h>\n#include <stdbool.h>\n#include <stddef.h>\n#include <stdint.h>\n#include <stdlib.h>\n#include <string.h>\n#include <math.h>\n'
def add(id, code, tests):
 source=HEADER+code
 # C top-level function bodies become explicit TODOs, keeping public types and signatures.
 matches=list(re.finditer(r'\)\s*\{',source)); replacements=[]
 for m in matches:
  pos=m.end()-1; prefix=source[:pos]; depth=prefix.count('{')-prefix.count('}')
  if depth: continue
  end=pos+1;nest=1
  while nest:
   if source[end]=='{':nest+=1
   if source[end]=='}':nest-=1
   end+=1
  replacements.append((pos,end,'{ /* TODO: implement this function. */ abort(); }'))
 starter=source
 for a,b,text in reversed(replacements):starter=starter[:a]+text+starter[b:]
 out[id]={'starter':starter,'solution':source,'tests':'int main(void) { '+tests+' return 0; }\n'}
add('fixed_steps','void fixed_steps(const unsigned *frames,size_t n,unsigned step,unsigned cap,unsigned *out){unsigned acc=0;for(size_t i=0;i<n;i++){acc+=frames[i];unsigned count=0;while(acc>=step&&count<cap){acc-=step;count++;}if(acc>=step)acc=0;out[i]=count;}}','unsigned f[]={16,16,16},out[3];fixed_steps(f,3,10,5,out);assert(out[0]==1&&out[1]==2&&out[2]==1);unsigned lag[]={100,9,1};fixed_steps(lag,3,10,5,out);assert(out[0]==5&&out[1]==0&&out[2]==1);fixed_steps(NULL,0,10,5,NULL);')
add('jumper','typedef struct {int coyote,buffer,left,pressed;bool has_left,has_press;} Jumper;void leave_ground(Jumper*j,int t){j->left=t;j->has_left=true;}bool press(Jumper*j,int t,bool grounded){if(grounded||(j->has_left&&t-j->left<=j->coyote)){j->has_left=false;j->has_press=false;return true;}j->pressed=t;j->has_press=true;return false;}bool land(Jumper*j,int t){j->has_left=false;bool fired=j->has_press&&t-j->pressed<=j->buffer;j->has_press=false;return fired;}','Jumper j={.coyote=100,.buffer=100};leave_ground(&j,1000);assert(press(&j,1060,false));assert(!press(&j,1070,false));assert(land(&j,1100));assert(!land(&j,1110));leave_ground(&j,2000);assert(!press(&j,2101,false));assert(!land(&j,2300));')
add('fsm','typedef enum{IDLE,RUNNING,AIR}State;typedef enum{RUN,STOP,JUMP,LAND,WAIT}Event;bool transition(State s,Event e,State*out){if(s==IDLE&&e==RUN)*out=RUNNING;else if((s==IDLE||s==RUNNING)&&e==JUMP)*out=AIR;else if(s==RUNNING&&e==STOP)*out=IDLE;else if(s==AIR&&e==LAND)*out=IDLE;else if(s==IDLE&&e==WAIT)*out=IDLE;else return false;return true;}typedef struct{State state;unsigned enters;}Machine;bool send(Machine*m,Event e){State next;if(!transition(m->state,e,&next))return false;if(next!=m->state){m->state=next;m->enters++;}return true;}','Machine m={IDLE,0};assert(send(&m,RUN)&&m.state==RUNNING);assert(!send(&m,LAND));assert(send(&m,JUMP)&&m.state==AIR);assert(send(&m,LAND));assert(m.enters==3);assert(send(&m,WAIT)&&m.enters==3);')
add('accel_clamp','typedef struct{double x,y;}Vec2;Vec2 accelerate(Vec2 v,Vec2 a,double dt,double max){Vec2 o={v.x+a.x*dt,v.y+a.y*dt};double speed=hypot(o.x,o.y);if(speed>max&&speed>0){o.x*=max/speed;o.y*=max/speed;}return o;}','Vec2 o=accelerate((Vec2){0,0},(Vec2){3,4},1,2);assert(fabs(o.x-1.2)<1e-9&&fabs(o.y-1.6)<1e-9);o=accelerate((Vec2){2,3},(Vec2){0,0},1,10);assert(o.x==2&&o.y==3);o=accelerate((Vec2){0,0},(Vec2){0,0},1,0);assert(o.x==0&&o.y==0);')
add('aabb','typedef struct{double x,y,w,h;}Rect;typedef struct{double x,y;}Vec2;bool overlaps(Rect a,Rect b){return a.x<b.x+b.w&&b.x<a.x+a.w&&a.y<b.y+b.h&&b.y<a.y+a.h;}Vec2 push_out(Rect a,Rect b){if(!overlaps(a,b))return (Vec2){0,0};double l=b.x-(a.x+a.w),r=b.x+b.w-a.x,t=b.y-(a.y+a.h),d=b.y+b.h-a.y;double x=fabs(l)<fabs(r)?l:r,y=fabs(t)<fabs(d)?t:d;return fabs(x)<fabs(y)?(Vec2){x,0}:(Vec2){0,y};}','assert(!overlaps((Rect){0,0,10,10},(Rect){10,0,10,10}));Vec2 v=push_out((Rect){8,0,10,10},(Rect){0,0,10,10});assert(v.x==2&&v.y==0);assert(!overlaps((Rect){10,0,10,10},(Rect){0,0,10,10}));')
add('sweep_hit','bool sweep_hit(double pos,double size,double dist,double wall,double*out){if(dist<=0)return false;double gap=wall-(pos+size);if(gap<0)return false;double t=gap/dist;if(t<0||t>1)return false;*out=t;return true;}','double t;assert(sweep_hit(0,2,20,12,&t)&&t==.5);assert(!sweep_hit(0,2,5,12,&t));assert(!sweep_hit(0,2,-20,12,&t));assert(!sweep_hit(10,5,20,12,&t));')
add('damp','double damp(double current,double target,double k,double dt){return target+(current-target)*exp(-k*dt);}','assert(damp(0,100,0,1)==0);double half=damp(0,100,2,.5);assert(fabs(half-63.212055882855765)<1e-9);assert(fabs(damp(damp(0,100,2,.25),100,2,.25)-half)<1e-9);')
add('pity','void simulate_pity(const double*rolls,size_t n,double probability,unsigned pity,bool*out){unsigned misses=0;for(size_t i=0;i<n;i++){bool hit=rolls[i]<probability||misses+1>=pity;out[i]=hit;misses=hit?0:misses+1;}}','double rolls[]={.9,.9,.9,.1,.9};bool out[5];simulate_pity(rolls,5,.2,3,out);assert(!out[0]&&!out[1]&&out[2]&&out[3]&&!out[4]);simulate_pity(NULL,0,.2,3,NULL);')
add('upgrade_cost','uint64_t upgrade_cost(uint64_t base,double growth,unsigned level){return (uint64_t)floor((double)base*pow(growth,level));}unsigned levels_affordable(uint64_t coins,uint64_t base,double growth,unsigned start,unsigned cap){unsigned n=0;while(n<cap){uint64_t c=upgrade_cost(base,growth,start+n);if(coins<c)break;coins-=c;n++;}return n;}','assert(upgrade_cost(100,1.5,2)==225);assert(levels_affordable(475,100,1.5,0,10)==3);assert(levels_affordable(99,100,1.5,0,10)==0);assert(levels_affordable(999,0,1.5,0,5)==5);')
add('rng_lcg','typedef struct{uint64_t state;}Rng;uint64_t rng_step(Rng*r){r->state=(1103515245ull*r->state+12345ull)% (1ull<<31);return r->state;}unsigned next_int(Rng*r,unsigned n){return (unsigned)((rng_step(r)>>16)%n);}double next_float(Rng*r){return (double)rng_step(r)/(double)(1ull<<31);}','Rng r={42};unsigned e[]={81,33,69,61,56,93};for(size_t i=0;i<6;i++)assert(next_int(&r,100)==e[i]);Rng f={7};assert(fabs(next_float(&f)-.5970560554414988)<1e-12);assert(fabs(next_float(&f)-.29926483193412423)<1e-12);')
add('integer_scale','typedef struct{int scale,off_x,off_y;}Fit;int floor_div(int a,int b){int q=a/b;if(a%b!=0&&((a<0)!=(b<0)))q--;return q;}Fit integer_scale(int w,int h,int bw,int bh){int s=w/bw<h/bh?w/bw:h/bh;if(s<1)s=1;return (Fit){s,floor_div(w-bw*s,2),floor_div(h-bh*s,2)};}','Fit f=integer_scale(1920,1080,320,180);assert(f.scale==6&&f.off_x==0&&f.off_y==0);f=integer_scale(1000,700,320,180);assert(f.scale==3&&f.off_x==20&&f.off_y==80);f=integer_scale(201,100,320,180);assert(f.scale==1&&f.off_x==-60&&f.off_y==-40);')
add('quantize','typedef struct{int r,g,b;}Rgb;size_t nearest_index(Rgb color,const Rgb*palette,size_t n){size_t best=0;long best_d=LONG_MAX;for(size_t i=0;i<n;i++){long r=color.r-palette[i].r,g=color.g-palette[i].g,b=color.b-palette[i].b,d=r*r+g*g+b*b;if(d<best_d){best_d=d;best=i;}}return best;}','Rgb p[]={{0,0,0},{255,255,255},{255,0,0}};assert(nearest_index((Rgb){250,5,5},p,3)==2);assert(nearest_index((Rgb){128,128,128},p,2)==1);Rgb tie[]={{0,0,0},{2,0,0}};assert(nearest_index((Rgb){1,0,0},tie,2)==0);')
add('spring_integrator','typedef struct{double x,v;}State;State semi_implicit(State s,double k,double dt){double v=s.v-k*s.x*dt;return (State){s.x+v*dt,v};}State velocity_verlet(State s,double k,double dt){double a=-k*s.x,x=s.x+s.v*dt+.5*a*dt*dt;return (State){x,s.v+.5*(a-k*x)*dt};}','State a=semi_implicit((State){1,0},4,.1);assert(fabs(a.x-.96)<1e-9&&fabs(a.v+.4)<1e-9);State b=velocity_verlet((State){1,0},4,.1);assert(fabs(b.x-.98)<1e-9&&fabs(b.v+.396)<1e-9);')
add('impulse_1d','typedef struct{double v1,v2;}Pair;Pair collide(double m1,double v1,double m2,double v2,double e){if(v1<=v2)return (Pair){v1,v2};double p=m1*v1+m2*v2,m=m1+m2;return (Pair){(p+m2*e*(v2-v1))/m,(p+m1*e*(v1-v2))/m};}','Pair a=collide(1,10,1,0,1);assert(a.v1==0&&a.v2==10);a=collide(1,10,1,0,0);assert(a.v1==5&&a.v2==5);a=collide(1,-10,1,0,1);assert(a.v1==-10&&a.v2==0);')
add('net_reconcile','typedef struct{uint32_t seq;int dx;}Input;int reconcile(int pos,uint32_t ack,const Input*p,size_t n){for(size_t i=0;i<n;i++)if(p[i].seq>ack)pos+=p[i].dx;return pos;}size_t drop_acked(const Input*p,size_t n,uint32_t ack){size_t i=0;while(i<n&&p[i].seq<=ack)i++;return i;}','Input p[]={{5,1},{6,1},{7,1},{8,2},{9,-1}};assert(reconcile(100,7,p,5)==101);assert(reconcile(100,9,p,5)==100);assert(reconcile(100,0,p,5)==104);assert(drop_acked(p,5,7)==3);assert(drop_acked(NULL,0,3)==0);')
add('snapshot_interp','typedef struct{double t,x;}Snapshot;bool interpolate(const Snapshot*s,size_t n,double t,double*out){if(!n)return false;if(t<=s[0].t){*out=s[0].x;return true;}if(t>=s[n-1].t){*out=s[n-1].x;return true;}size_t i=0;while(i+1<n&&s[i+1].t<=t)i++;double d=s[i+1].t-s[i].t;*out=d==0?s[i+1].x:s[i].x+(s[i+1].x-s[i].x)*(t-s[i].t)/d;return true;}','Snapshot s[]={{1,10},{1.1,20},{1.3,60}};double v;assert(interpolate(s,3,1.05,&v)&&fabs(v-15)<1e-9);assert(interpolate(s,3,1.2,&v)&&fabs(v-40)<1e-9);assert(interpolate(s,3,9,&v)&&v==60);assert(!interpolate(NULL,0,1,&v));')
