add('sparse_set','enum{CAPACITY=8};typedef struct{unsigned ids[CAPACITY],sparse[CAPACITY];int values[CAPACITY];size_t n;}SparseSet;bool has(const SparseSet*s,unsigned id){return id<CAPACITY&&s->sparse[id]<s->n&&s->ids[s->sparse[id]]==id;}bool insert(SparseSet*s,unsigned id,int value){if(id>=CAPACITY)return false;if(has(s,id)){s->values[s->sparse[id]]=value;return true;}if(s->n==CAPACITY)return false;s->sparse[id]=(unsigned)s->n;s->ids[s->n]=id;s->values[s->n++]=value;return true;}bool get(const SparseSet*s,unsigned id,int*out){if(!has(s,id))return false;*out=s->values[s->sparse[id]];return true;}bool remove_id(SparseSet*s,unsigned id){if(!has(s,id))return false;unsigned slot=s->sparse[id];size_t last=--s->n;s->ids[slot]=s->ids[last];s->values[slot]=s->values[last];s->sparse[s->ids[slot]]=slot;return true;}','SparseSet s={0};int v;assert(!has(&s,1));assert(insert(&s,1,10)&&insert(&s,3,20));assert(get(&s,3,&v)&&v==20);assert(insert(&s,1,11)&&s.n==2);assert(remove_id(&s,1));assert(!has(&s,1)&&get(&s,3,&v)&&v==20);assert(!remove_id(&s,1));assert(!insert(&s,8,5));assert(insert(&s,1,12));')
add('free_list_pool','enum{CAPACITY=8};typedef struct{int values[CAPACITY];size_t next[CAPACITY],head,free_count;bool live[CAPACITY];}Pool;void pool_init(Pool*p){memset(p,0,sizeof(*p));p->free_count=CAPACITY;for(size_t i=0;i<CAPACITY;i++)p->next[i]=i+1;}int*acquire(Pool*p){if(p->head==CAPACITY)return NULL;size_t slot=p->head;p->head=p->next[slot];p->live[slot]=true;p->free_count--;return &p->values[slot];}bool release(Pool*p,int*value){size_t slot=CAPACITY;for(size_t i=0;i<CAPACITY;i++)if(value==&p->values[i]){slot=i;break;}if(slot==CAPACITY||!p->live[slot])return false;p->live[slot]=false;p->next[slot]=p->head;p->head=slot;p->free_count++;return true;}','Pool p;pool_init(&p);int*slots[8];for(size_t i=0;i<8;i++){slots[i]=acquire(&p);assert(slots[i]);}assert(!acquire(&p)&&p.free_count==0);assert(release(&p,slots[3]));assert(!release(&p,slots[3]));assert(acquire(&p)==slots[3]);int foreign;assert(!release(&p,&foreign));')
add('event_queue','enum{CAPACITY=8};typedef struct{int items[CAPACITY];size_t head,count;}RingQueue;bool queue_push(RingQueue*q,int v){if(q->count==CAPACITY)return false;q->items[(q->head+q->count)%CAPACITY]=v;q->count++;return true;}bool queue_pop(RingQueue*q,int*out){if(!q->count)return false;*out=q->items[q->head];q->head=(q->head+1)%CAPACITY;q->count--;return true;}','RingQueue q={0};int v;assert(!queue_pop(&q,&v));for(int i=0;i<8;i++)assert(queue_push(&q,i));assert(!queue_push(&q,9));for(int i=0;i<4;i++){assert(queue_pop(&q,&v));assert(v==i);}for(int i=8;i<12;i++)assert(queue_push(&q,i));for(int i=4;i<12;i++){assert(queue_pop(&q,&v));assert(v==i);}assert(!queue_pop(&q,&v));')
add('grid_path','typedef struct{int row,col;}Cell;int shortest_path(const char*const*grid,int rows,int cols,Cell start,Cell goal){if(rows<=0||cols<=0||start.row<0||start.col<0||goal.row<0||goal.col<0||start.row>=rows||goal.row>=rows||start.col>=cols||goal.col>=cols||grid[start.row][start.col]==\'#\'||grid[goal.row][goal.col]==\'#\')return -1;size_t count=(size_t)rows*(size_t)cols;int*dist=(int*)malloc(count*sizeof(int));Cell*q=(Cell*)malloc(count*sizeof(Cell));if(!dist||!q){free(dist);free(q);return -1;}for(size_t i=0;i<count;i++)dist[i]=-1;size_t head=0,tail=0;q[tail++]=start;dist[start.row*cols+start.col]=0;int answer=-1,dr[]={1,-1,0,0},dc[]={0,0,1,-1};while(head<tail){Cell c=q[head++];int d=dist[c.row*cols+c.col];if(c.row==goal.row&&c.col==goal.col){answer=d;break;}for(int k=0;k<4;k++){Cell n={c.row+dr[k],c.col+dc[k]};if(n.row<0||n.col<0||n.row>=rows||n.col>=cols||grid[n.row][n.col]==\'#\'||dist[n.row*cols+n.col]!=-1)continue;dist[n.row*cols+n.col]=d+1;q[tail++]=n;}}free(q);free(dist);return answer;}','const char*g[]={".#.","..."};assert(shortest_path(g,2,3,(Cell){0,0},(Cell){0,2})==4);assert(shortest_path(g,2,3,(Cell){0,0},(Cell){0,0})==0);assert(shortest_path(g,2,3,(Cell){0,1},(Cell){0,2})==-1);const char*w[]={".#."};assert(shortest_path(w,1,3,(Cell){0,0},(Cell){0,2})==-1);')
add('ca_smooth','void smooth(const char*const*grid,int h,int w,char*out){for(int y=0;y<h;y++)for(int x=0;x<w;x++){int walls=0;for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){if(dx==0&&dy==0)continue;int nx=x+dx,ny=y+dy;if(nx<0||ny<0||nx>=w||ny>=h||grid[ny][nx]==\'#\')walls++;}out[y*w+x]=walls>=5?\'#\':\'.\';}}','const char*g[]={"...","...","..."};char out[9];smooth(g,3,3,out);assert(memcmp(out,"#.#...#.#",9)==0);const char*s[]={"."};smooth(s,1,1,out);assert(out[0]==\'#\');smooth(NULL,0,0,NULL);')
add('autotile','bool solid(const char*const*g,int h,int w,int row,int col){return row<0||col<0||row>=h||col>=w||g[row][col]==\'#\';}unsigned bitmask(const char*const*g,int h,int w,int row,int col){return (solid(g,h,w,row-1,col)?1u:0u)|(solid(g,h,w,row,col+1)?2u:0u)|(solid(g,h,w,row+1,col)?4u:0u)|(solid(g,h,w,row,col-1)?8u:0u);}','const char*g[]={".#.","#.#",".#."};assert(bitmask(g,3,3,1,1)==15);const char*e[]={"...","...","..."};assert(bitmask(e,3,3,1,1)==0);assert(bitmask(e,3,3,0,0)==9);')
add('save_codec','typedef struct{uint32_t coins;uint16_t level;}Save;uint8_t checksum(const uint8_t*p,size_t n){uint8_t sum=0;for(size_t i=0;i<n;i++)sum=(uint8_t)(sum+p[i]);return sum;}void encode(Save s,uint8_t*out){out[0]=\'S\';out[1]=2;for(int i=0;i<4;i++)out[2+i]=(uint8_t)(s.coins>>(8*i));out[6]=(uint8_t)s.level;out[7]=(uint8_t)(s.level>>8);out[8]=checksum(out,8);}bool decode(const uint8_t*b,size_t n,Save*out){if(n<2||b[0]!=\'S\')return false;if(b[1]==2){if(n!=9||b[8]!=checksum(b,8))return false;out->coins=(uint32_t)b[2]|((uint32_t)b[3]<<8)|((uint32_t)b[4]<<16)|((uint32_t)b[5]<<24);out->level=(uint16_t)(b[6]|(b[7]<<8));return true;}if(b[1]==1){if(n!=6||b[5]!=checksum(b,5))return false;out->coins=b[2]|(b[3]<<8);out->level=b[4];return true;}return false;}','uint8_t b[9];encode((Save){0x01020304,0x0506},b);uint8_t expected[]={0x53,2,4,3,2,1,6,5,0x6A};assert(memcmp(b,expected,9)==0);Save out;assert(decode(b,9,&out)&&out.coins==0x01020304&&out.level==0x0506);b[8]^=1;assert(!decode(b,9,&out));uint8_t v1[]={0x53,1,0x2C,1,7,0x88};assert(decode(v1,6,&out)&&out.coins==300&&out.level==7);assert(!decode(NULL,0,&out));')
add('utility_pick','double score(const double*c,size_t n){double s=1;for(size_t i=0;i<n;i++)s*=fmax(0,fmin(1,c[i]));return s;}bool pick(const double*s,size_t n,int current,double inertia,size_t*out){if(!n)return false;size_t best=0;double v=s[0]+(current==0?inertia:0);for(size_t i=1;i<n;i++){double x=s[i]+(current==(int)i?inertia:0);if(x>v){best=i;v=x;}}*out=best;return true;}','double c[]={.5,2,-1};assert(score(c,2)==.5&&score(c,3)==0);assert(score(NULL,0)==1);double s[]={.5,.6};size_t out;assert(pick(s,2,0,.2,&out)&&out==0);assert(pick(s,2,-1,0,&out)&&out==1);assert(!pick(NULL,0,-1,0,&out));')
add('behavior_tree','typedef enum{SUCCESS,FAILURE,RUNNING}Status;typedef enum{LEAF,SEQUENCE,SELECTOR,INVERTER}Kind;typedef struct{Kind kind;size_t a,b;}Node;Status tick(const Node*nodes,const size_t*kids,const Status*results,size_t root){Node n=nodes[root];switch(n.kind){case LEAF:return results[n.a];case INVERTER:{Status s=tick(nodes,kids,results,n.a);return s==SUCCESS?FAILURE:s==FAILURE?SUCCESS:RUNNING;}case SEQUENCE:for(size_t i=n.a;i<n.a+n.b;i++){Status s=tick(nodes,kids,results,kids[i]);if(s!=SUCCESS)return s;}return SUCCESS;case SELECTOR:for(size_t i=n.a;i<n.a+n.b;i++){Status s=tick(nodes,kids,results,kids[i]);if(s!=FAILURE)return s;}return FAILURE;}return FAILURE;}','Node nodes[]={{LEAF,0,0},{LEAF,1,0},{SEQUENCE,0,2},{SELECTOR,0,2},{INVERTER,0,0}};size_t kids[]={0,1};Status results[]={SUCCESS,RUNNING};assert(tick(nodes,kids,results,2)==RUNNING);assert(tick(nodes,kids,results,3)==SUCCESS);assert(tick(nodes,kids,results,4)==FAILURE);results[0]=FAILURE;assert(tick(nodes,kids,results,2)==FAILURE);assert(tick(nodes,kids,results,3)==RUNNING);')
add('transform2d','typedef struct{double a,b,c,d,tx,ty;}Mat;typedef struct{double x,y;}Point;Mat translate(double x,double y){return (Mat){1,0,0,1,x,y};}Mat rotate(double rad){double co=cos(rad),si=sin(rad);return (Mat){co,si,-si,co,0,0};}Mat scale(double x,double y){return (Mat){x,0,0,y,0,0};}Mat mul(Mat p,Mat c){return (Mat){p.a*c.a+p.c*c.b,p.b*c.a+p.d*c.b,p.a*c.c+p.c*c.d,p.b*c.c+p.d*c.d,p.a*c.tx+p.c*c.ty+p.tx,p.b*c.tx+p.d*c.ty+p.ty};}Point apply(Mat m,Point p){return (Point){m.a*p.x+m.c*p.y+m.tx,m.b*p.x+m.d*p.y+m.ty};}bool inverse(Mat m,Mat*out){double det=m.a*m.d-m.b*m.c;if(fabs(det)<1e-12)return false;double a=m.d/det,b=-m.b/det,c=-m.c/det,d=m.a/det;*out=(Mat){a,b,c,d,-(a*m.tx+c*m.ty),-(b*m.tx+d*m.ty)};return true;}','Mat m=mul(translate(3,4),scale(2,3));Point p=apply(m,(Point){1,2});assert(p.x==5&&p.y==10);Mat inv;assert(inverse(m,&inv));p=apply(inv,p);assert(fabs(p.x-1)<1e-9&&fabs(p.y-2)<1e-9);assert(!inverse(scale(0,1),&inv));p=apply(rotate(acos(-1)/2),(Point){1,0});assert(fabs(p.x)<1e-9&&fabs(p.y-1)<1e-9);')
out.update(json.loads((ROOT/'scripts/native/game-drills-c-extra.json').read_text()))
